export function readSaga(){try{return cleanSaga(JSON.parse(localStorage.getItem(KEY)||'{}'));}catch{return cleanSaga();}}
export function sagaRecord(p,id){return p.chapters[id]||emptyRecord();}
export function sagaUnlocked(p,id){const i=CHAPTERS.findIndex(c=>c.id===id);return i===0||i>0&&p.chapters?.[CHAPTERS[i-1].id]?.completed===true;}
export function saveSaga(p){const progress=cleanSaga(p);try{localStorage.setItem(KEY,JSON.stringify(progress));return {progress,saved:true};}catch{return {progress,saved:false};}}
export function finishSaga(p,id,time,combo,orbs){const out=cleanSaga(p);if(!sagaUnlocked(out,id)||!CHAPTERS.some(c=>c.id===id))return {progress:out,saved:false};const old=sagaRecord(out,id);out.chapters[id]={completed:true,bestTime:old.bestTime?Math.min(old.bestTime,time):time,bestCombo:Math.max(old.bestCombo,combo),orbs:Math.max(old.orbs,orbs)};return saveSaga(out);}
export function buySkill(p,id){const out=cleanSaga(p),s=SKILLS.find(s=>s.id===id);if(!s||s.auto||out.skills.includes(id)||out.points<s.cost||!s.requires.every(id=>out.skills.includes(id))||s.chapter&&!sagaUnlocked(out,s.chapter))return {progress:out,saved:false,reason:'Requisitos ainda não atendidos.'};out.skills.push(id);return saveSaga(out);}
